package cn.kejian;
import android.content.Context;import android.util.AtomicFile;import org.json.*;import java.nio.file.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class IOConcurrencyTest {
 public static void main(String[] args)throws Exception{java.io.File dir=Files.createTempDirectory("kejian-repo-test").toFile();Context context=new Context(dir);JSONObject data=new JSONObject("{\"updated\":1,\"weeks\":[{\"number\":1,\"start\":\"2026-11-02\",\"end\":\"2026-11-08\",\"state\":\"empty\",\"courses\":[]}]}");ScheduleRepository.parse(data).save(context);data.put("updated",2);AtomicReference<Throwable> failure=new AtomicReference<>();AtomicFile.block=true;Thread writer=new Thread(()->{try{ScheduleRepository.parse(data).save(context);}catch(Throwable e){failure.set(e);}});writer.start();if(!AtomicFile.entered.await(2,TimeUnit.SECONDS))throw new AssertionError("writer never entered");CountDownLatch readStarted=new CountDownLatch(1),readDone=new CountDownLatch(1);Thread reader=new Thread(()->{readStarted.countDown();ScheduleRepository r=new ScheduleRepository(context);if(r.corrupt||r.updated!=2)failure.set(new AssertionError("read overlapped write or saw stale data"));readDone.countDown();});reader.start();readStarted.await();boolean raced=readDone.await(150,TimeUnit.MILLISECONDS);AtomicFile.release.countDown();writer.join(2000);reader.join(2000);if(raced||failure.get()!=null)throw new AssertionError("repository read/write must share one lock",failure.get());ScheduleRepository.clear(context);if(new ScheduleRepository(context).raw!=null)throw new AssertionError("clear failed");dir.delete();System.out.println("PASS repository serializes background reads with saves and clear");}
}
